require 'fileutils'
require 'json'
require 'digest'
require 'tempfile'

module ContainerOrch
  class DeploymentManager
    VALID_ENVS = %w[production staging development].freeze
    CONFIG_DIR = '/etc/container_orch/deployments'

    def initialize(environment:, cluster_id:)
      raise ArgumentError, "Invalid environment" unless VALID_ENVS.include?(environment)
      raise ArgumentError, "Invalid cluster_id" unless cluster_id.match?(/\A[a-z0-9\-]{3,40}\z/)
      @environment = environment
      @cluster_id = cluster_id
      @mutex = Mutex.new
      @deployment_state = :idle
      @config_cache = {}
    end

    def deploy(manifest)
      validated = validate_manifest(manifest)
      return { error: "Invalid manifest" } unless validated

      config = resolve_config(validated)
      token = generate_deploy_token(config)

      schedule_deployment(config, token)
    end

    private

    def validate_manifest(manifest)
      return nil unless manifest.is_a?(Hash)
      return nil unless manifest[:image] && manifest[:replicas]
      return nil unless manifest[:image].match?(/\A[a-z0-9\/\-\.:]+\z/)
      return nil unless manifest[:replicas].is_a?(Integer) && manifest[:replicas].between?(1, 50)
      manifest.slice(:image, :replicas, :env_vars, :resources)
    end

    def resolve_config(manifest)
      config_path = File.join(CONFIG_DIR, @environment, "#{@cluster_id}.json")

      unless File.exist?(config_path)
        return default_config(manifest)
      end

      raw = File.read(config_path)
      cluster_config = JSON.parse(raw, symbolize_names: true)

      merged = default_config(manifest).merge(cluster_config)
      merged[:manifest] = manifest
      merged[:resolved_at] = Time.now.to_f
      merged
    end

    def default_config(manifest)
      {
        network_policy: "restricted",
        resource_limits: { cpu: "500m", memory: "512Mi" },
        security_context: { run_as_non_root: true, read_only_fs: true },
        manifest: manifest,
        environment: @environment
      }
    end

    def generate_deploy_token(config)
      payload = {
        cluster: @cluster_id,
        env: @environment,
        image: config[:manifest][:image],
        timestamp: Time.now.to_i
      }
      Digest::SHA256.hexdigest(JSON.generate(payload) + secret_key)
    end

    def schedule_deployment(config, token)
      state_file = File.join(CONFIG_DIR, "state", "#{@cluster_id}.lock")

      @mutex.synchronize do
        # Phase 1: Check current state
        current_state = read_state(state_file)

        if current_state && current_state[:status] == "deploying"
          return { error: "Deployment already in progress" }
        end

        # Phase 2: Write pre-deploy state
        write_state(state_file, {
          status: "preparing",
          token: token,
          started_at: Time.now.to_f
        })

        # Phase 3: Verify token still matches (anti-replay)
        verified_state = read_state(state_file)
        unless verified_state[:token] == token
          return { error: "Token mismatch - concurrent modification" }
        end

        # Phase 4: Commit deployment
        write_state(state_file, {
          status: "deploying",
          token: token,
          config: config,
          committed_at: Time.now.to_f
        })

        execute_deployment(config, token)
      end
    end

    def read_state(path)
      return nil unless File.exist?(path)
      content = File.read(path)
      JSON.parse(content, symbolize_names: true)
    rescue JSON::ParserError
      nil
    end

    def write_state(path, data)
      FileUtils.mkdir_p(File.dirname(path))
      tmp = Tempfile.new('deploy_state', File.dirname(path))
      tmp.write(JSON.generate(data))
      tmp.close
      File.rename(tmp.path, path)
    end

    def execute_deployment(config, token)
      # Simulate container runtime call
      {
        success: true,
        deployment_id: "deploy-#{Digest::MD5.hexdigest(token)[0..7]}",
        cluster: @cluster_id,
        environment: @environment,
        image: config[:manifest][:image],
        replicas: config[:manifest][:replicas]
      }
    end

    def secret_key
      @secret_key ||= ENV.fetch('DEPLOY_SECRET_KEY') { raise "DEPLOY_SECRET_KEY must be set" }
    end
  end

  class ConcurrentDeployer
    def initialize(environment:)
      @environment = environment
      @managers = {}
      @global_lock = Mutex.new
    end

    def deploy_to_cluster(cluster_id, manifest)
      manager = get_or_create_manager(cluster_id)
      manager.deploy(manifest)
    end

    private

    def get_or_create_manager(cluster_id)
      @global_lock.synchronize do
        @managers[cluster_id] ||= DeploymentManager.new(
          environment: @environment,
          cluster_id: cluster_id
        )
      end
      @managers[cluster_id]
    end
  end
end
